<script setup>
import {ref,reactive,onBeforeUnmount,computed} from 'vue';
import {Button,Form,Field,RadioGroup,Radio,Checkbox,DropdownMenu,DropdownItem,Pagination,Loading,Tag} from 'vant';
import HomeSample from './HomeSample.vue';
import 'vant/es/dropdown-menu/style';
import 'vant/es/dropdown-item/style';
import 'vant/es/pagination/style';
const {controller}=defineProps({controller:{type:Object,required:true}}),m=ref(controller.model),a=controller.actions;
const off=controller.subscribe(value=>m.value=value);onBeforeUnmount(off);
const draft=reactive({username:'',password:'',displayName:'',role:'',consent:false}),localError=ref('');
const subjects=[{text:'全部科目',value:''},{text:'数学',value:'math'},{text:'英语',value:'english'},{text:'物理',value:'physics'}],terms=[{text:'全部学期',value:''},{text:'上学期 · 八年级上册',value:'upper'},{text:'下学期 · 八年级下册',value:'lower'}],kinds=[{text:'单元排行榜',value:'unit'},{text:'学期科目排行榜',value:'course'}];
const boards=computed(()=>(m.value.choices||[]).map(b=>({text:b.title,value:b.id}))),percent=n=>Number(n).toFixed(1)+'%',points=n=>Number(n).toFixed(2);
async function submit(){localError.value='';if((m.value.mode==='register'||m.value.kind==='role')&&!['Student','Parent'].includes(draft.role)){localError.value='请选择学生或家长。';return;}if(m.value.native&&m.value.mode==='register'&&!draft.consent){localError.value='请先确认云账号关联。';return;}const values=m.value.kind==='role'?{role:draft.role}:{...draft};try{await a.submit(values);}finally{draft.password='';}}
</script>
<template>
 <header v-if="m.kind==='navigation'" class="student-platform-nav"><HomeSample :key="m.identity" :adapter="m.adapter"/><a class="platform-brand" href="/" aria-label="逆流学习首页"><img :src="'vendor/brand/logo.webp'" alt="" width="40" height="40"/>逆流</a><div class="platform-nav-actions"><Button v-if="m.canDownload" :loading="m.downloading" @click="a.download">下载 APK</Button><Button v-if="m.returnTo" tag="a" :href="m.returnTo">返回后台</Button></div></header>
 <section v-else-if="m.kind==='auth'||m.kind==='role'" class="student-platform-auth"><p class="eyebrow">逆流 · 学习与陪伴</p><h1>{{m.kind==='role'?'请选择你的身份':m.mode==='register'?'创建云账号':'欢迎回来'}}</h1><p>{{m.kind==='role'?'确认你是学生还是家长，继续使用学习服务。':'学生继续学习，家长看见进步。'}}</p>
  <Form @submit="submit"><template v-if="m.kind==='auth'"><Field v-model="draft.username" name="username" label="账号" autocomplete="username" maxlength="24" :rules="[{required:true,message:'请输入账号'},{validator:v=>v.length>=2,message:'账号至少2个字符'}]"/><Field v-model="draft.password" name="password" label="密码" type="password" :autocomplete="m.mode==='register'?'new-password':'current-password'" maxlength="128" :rules="[{required:true,message:'请输入密码'},{validator:v=>v.length>=8,message:'密码至少8位'}]"/><Field v-if="m.mode==='register'" v-model="draft.displayName" label="称呼" maxlength="40" :rules="[{required:true,message:'请输入称呼'}]"/></template>
   <Field v-if="m.kind==='role'||m.mode==='register'" label="身份"><template #input><RadioGroup v-model="draft.role"><Radio name="Student">我是学生</Radio><Radio name="Parent">我是家长</Radio></RadioGroup></template></Field>
   <Checkbox v-if="m.native&&m.mode==='register'" v-model="draft.consent">同意登录云账号并关联本机学习记录</Checkbox><p v-if="localError||m.error" role="alert">{{localError||m.error}}</p><Button native-type="submit" type="primary" block :loading="m.busy">{{m.kind==='role'?'保存身份并继续':m.mode==='register'?'注册并登录':'登录'}}</Button>
  </Form><Button v-if="m.kind==='auth'" block plain @click="a.switch">{{m.mode==='register'?'已有账号？登录':'还没有账号？注册'}}</Button><p class="platform-note">本机记录和 AI 密钥保留，切换账号后学习记录分别保存。</p>
 </section>
 <section v-else-if="m.kind==='rankings'" class="student-platform-rankings"><header><h2>我的排行榜</h2><Button icon="cross" class="platform-close" aria-label="关闭排行榜" @click="a.close"/></header><Button :loading="m.busy" @click="a.refresh">刷新排行榜</Button><DropdownMenu><DropdownItem :model-value="m.subject" :options="subjects" @change="a.filter('subject',$event)"/><DropdownItem :model-value="m.term" :options="terms" @change="a.filter('term',$event)"/><DropdownItem :model-value="m.boardKind" :options="kinds" @change="a.filter('boardKind',$event)"/></DropdownMenu><Field label="已开始课程"><template #input><DropdownMenu><DropdownItem :model-value="m.selected" :disabled="!boards.length" :options="boards" :title="boards.length?undefined:'暂无课程'" @change="a.filter('selected',$event)"/></DropdownMenu></template></Field><p v-if="m.error" role="alert">{{m.error}}<Button @click="a.refresh">重试</Button></p><p v-if="m.busy" role="status"><Loading size="20"/>正在读取排行榜…</p><template v-else-if="m.data"><h3>{{m.data.board.title}}</h3><p class="ranking-self"><strong>第 {{m.data.self.rank}} 名</strong><strong>{{points(m.data.self.score)}} 分</strong></p><div class="ranking-table" role="region" tabindex="0" aria-label="排行榜，可横向滚动"><table><thead><tr><th>名次</th><th>同学</th><th>{{m.data.board.subject==='english'?'单词默写 50%':'费曼学习 30%'}}</th><th>{{m.data.board.subject==='english'?'句子闯关 50%':'应用练习 70%'}}</th><th>总分</th></tr></thead><tbody><tr v-for="row in m.data.rows" :key="row.rank" :aria-current="row.isSelf?'true':undefined"><td>{{row.rank}}</td><td>{{row.label}}<Tag v-if="row.isSelf" type="success">当前学生</Tag></td><td>{{percent(row.conceptPercent)}}</td><td>{{percent(row.testPercent)}}</td><td>{{points(row.score)}}</td></tr></tbody></table></div><Pagination :model-value="m.page" :total-items="m.data.total" :items-per-page="m.data.pageSize" :show-page-size="3" force-ellipses @update:model-value="a.page"/></template><p v-else-if="!m.busy&&!m.error">暂无对应的已学习课程。</p></section>
 <section v-else class="student-platform-auth"><p role="status">{{m.message}}</p><Button v-if="a.login" @click="a.login">账号登录</Button></section>
</template>
<style scoped>
.student-platform-auth,.student-platform-rankings,.student-platform-nav{--van-primary-color:#38694f;color:#26362d;font-family:system-ui,-apple-system,'Microsoft YaHei',sans-serif;box-sizing:border-box}.student-platform-auth{max-width:470px;margin:clamp(24px,8vh,80px) auto;padding:24px}.student-platform-auth h1{font-size:30px;margin:16px 0}.student-platform-auth p{line-height:1.8}.eyebrow,.platform-note{color:#69776d;font-size:14px}.student-platform-auth :deep(.van-field){padding:16px 0}.student-platform-auth :deep(.van-radio){margin:12px 0}.student-platform-auth :deep(.van-button--block){margin-top:16px}.student-platform-auth [role=alert],.student-platform-rankings [role=alert]{color:#b42318}.student-platform-nav{display:flex;gap:16px;align-items:center;padding:12px clamp(12px,3vw,36px);background:#fff;border-bottom:1px solid #e3e8e1}.platform-brand{display:flex;gap:8px;align-items:center;color:#26362d;font-size:22px;font-weight:700;text-decoration:none}.platform-brand img{border-radius:10px}.platform-nav-actions{margin-left:auto;display:flex;gap:8px}.student-platform-rankings{padding:20px;max-width:100%;width:min(920px,90vw);min-height:240px;background:#fff}.student-platform-rankings>header{display:flex;align-items:center;justify-content:space-between;gap:16px}.platform-close.van-button{width:44px;height:44px;padding:0;flex-shrink:0}.student-platform-rankings h2{font-size:22px}.student-platform-rankings h3{font-size:18px}.ranking-self{display:flex;gap:24px;flex-wrap:wrap;font-size:24px}.ranking-table{overflow:auto;max-width:100%;margin:16px 0}.ranking-table table{border-collapse:collapse;width:100%;font-size:14px}.ranking-table th,.ranking-table td{padding:14px;text-align:left;white-space:nowrap;border-bottom:1px solid #e3e8e1}.ranking-table [aria-current=true]{background:#eef5ef}.student-platform-auth :deep(.van-field__control),.student-platform-rankings :deep(.van-field__control){padding:0;background:transparent;border:0;box-shadow:none;font:inherit}.student-platform-auth :deep(.van-button),.student-platform-nav :deep(.van-button),.student-platform-rankings :deep(.van-button){min-height:44px;font:inherit}.student-platform-rankings :deep(.van-dropdown-menu__bar){box-shadow:none}.student-platform-rankings :deep(.van-field__value){min-width:0}.student-platform-rankings :deep(.van-field__body>.van-dropdown-menu){width:100%}.student-platform-rankings :deep(.van-pagination){padding:0}@media(max-width:480px){.student-platform-nav{gap:8px}.platform-brand{font-size:19px;gap:5px}.platform-brand img{width:32px;height:32px}.student-platform-rankings{padding:14px;width:100%}.student-platform-auth{padding:20px 14px}.student-platform-rankings :deep(.van-dropdown-menu__title){font-size:13px}}
</style>
<style scoped>
