.student-platform-auth,.student-platform-rankings,.student-platform-nav{--van-primary-color:#25332c;color:#25332c;font-family:"Segoe UI","Microsoft YaHei",system-ui,sans-serif;font-size:15px;line-height:1.65;font-variant-numeric:tabular-nums}
.student-platform-auth{max-width:480px;margin:6vh auto;padding:32px;background:#fff;border:1px solid #e0e6e1;border-radius:12px}.student-platform-auth h1{font-size:26px;font-weight:600;line-height:1.4;margin:0 0 12px}.student-platform-auth p{margin:14px 0}.eyebrow,.platform-note{color:#5e6b63;font-size:14px}
.student-platform-auth :deep(.van-field){display:block;padding:0;margin:16px 0;background:transparent}.student-platform-auth :deep(.van-field:after){display:none}.student-platform-auth :deep(.van-field__label){width:auto;font-size:14px;font-weight:500;margin-bottom:7px}.student-platform-auth :deep(.van-field__control){width:100%;min-height:40px;padding:10px 12px;border:1px solid #b8c5bc;border-radius:8px;background:#fff;font:inherit}.student-platform-auth :deep(.van-button--block){display:inline-flex;width:auto;margin:0 0 12px}.student-platform-auth :deep(.van-button--primary){background:#25332c;border-color:#25332c;color:#fff}
.student-platform-nav{padding:12px max(20px,calc((100vw - 1200px)/2));gap:14px;background:#f5f7f5;border-color:#e0e6e1}.platform-brand{font-size:21px;font-weight:600;color:#25332c}.platform-brand img{width:38px;height:38px;border-radius:8px}
.student-platform-auth :deep(.van-button),.student-platform-nav :deep(.van-button),.student-platform-rankings :deep(.van-button){height:auto;min-height:40px;padding:8px 14px;border:1px solid #b8c5bc;border-radius:8px;background:#fff;color:#25332c;font:14px/1.5 "Segoe UI","Microsoft YaHei",system-ui,sans-serif;box-shadow:none}.student-platform-auth :deep(.van-button--primary){background:#25332c;border-color:#25332c;color:#fff}.platform-close.van-button{min-height:44px;width:44px;padding:0}
.student-platform-rankings{width:min(920px,90vw);padding:24px;background:#fff}.student-platform-rankings h2{font-size:20px;font-weight:600}.student-platform-rankings h3{font-size:18px}.ranking-self{justify-content:space-between;align-items:center;padding:22px;background:#f0f5eb;border:1px solid #e0e6e1;border-radius:12px;margin:20px 0;font-size:28px}.ranking-self strong{font-weight:400}.ranking-table td,.ranking-table th{padding:12px;border-color:#e0e6e1;font-size:15px}.student-platform-rankings :deep(.van-dropdown-menu__bar){background:transparent;height:auto;gap:12px}.student-platform-rankings :deep(.van-dropdown-menu__item){min-height:44px;padding:10px 24px 10px 12px;border:1px solid #b8c5bc;border-radius:8px;background:white}.student-platform-rankings :deep(.van-cell){background:transparent}.student-platform-rankings :deep(.van-field__label){font-size:14px}.student-platform-rankings :deep(.van-tag){border-radius:5px;background:#eef2ef;color:#38694f}
@media(max-width:600px){.student-platform-nav{padding:10px 16px;gap:10px}.student-platform-auth{padding:24px}.student-platform-auth h1{font-size:23px}.student-platform-rankings{padding:18px;width:100%}.student-platform-rankings h2{font-size:21px}.ranking-self{gap:18px;padding:16px;font-size:26px}.student-platform-auth :deep(.van-button),.student-platform-nav :deep(.van-button),.student-platform-rankings :deep(.van-button){min-height:44px}}
</style>
